    function nfmt(v) {
        var s = String(v);
        return s.replace('.', ',');
    }

    function treeDiagram(pA, pNotA, pB1, pNotB1, pB2, pNotB2) {
        return `<svg viewBox="0 0 420 190" xmlns="http://www.w3.org/2000/svg" style="max-width:100%;height:auto;display:block;margin:8px auto">
          <g fill="none" stroke="#333" stroke-width="2">
            <line x1="210" y1="22" x2="115" y2="78"/><line x1="210" y1="22" x2="305" y2="78"/>
            <line x1="115" y1="78" x2="65" y2="150"/><line x1="115" y1="78" x2="165" y2="150"/>
            <line x1="305" y1="78" x2="255" y2="150"/><line x1="305" y1="78" x2="355" y2="150"/>
          </g>
          <g font-family="serif" font-size="17" fill="#111" text-anchor="middle">
            <text x="210" y="18">S</text><text x="115" y="73">A</text><text x="305" y="73">Ā</text>
            <text x="65" y="174">B</text><text x="165" y="174">B̄</text><text x="255" y="174">B</text><text x="355" y="174">B̄</text>
            <text x="151" y="45">${nfmt(pA)}</text><text x="269" y="45">${nfmt(pNotA)}</text>
            <text x="80" y="112">${nfmt(pB1)}</text><text x="151" y="112">${nfmt(pNotB1)}</text>
            <text x="270" y="112">${nfmt(pB2)}</text><text x="341" y="112">${nfmt(pNotB2)}</text>
          </g>
        </svg>`;
    }

    function vennFrame(inner) {
        return `<svg viewBox="0 0 340 155" xmlns="http://www.w3.org/2000/svg" style="max-width:100%;height:auto;display:block;margin:8px auto">
          <rect x="12" y="12" width="316" height="130" fill="none" stroke="#333" stroke-width="1.6"/>
          <ellipse cx="135" cy="78" rx="78" ry="48" fill="none" stroke="#333" stroke-width="1.6"/>
          <ellipse cx="205" cy="78" rx="78" ry="48" fill="none" stroke="#333" stroke-width="1.6"/>
          <text x="38" y="78" font-family="serif" font-style="italic" font-size="18">A</text>
          <text x="292" y="78" font-family="serif" font-style="italic" font-size="18">B</text>
          ${inner}
        </svg>`;
    }

    const POS = {
      o:[[305,28],[300,125],[25,25],[315,105],[25,125],[275,25],[44,116],[296,50],[45,35],[307,92]],
      a:[[92,60],[105,92],[125,48],[80,82],[118,110],[72,52],[100,118],[128,70],[88,105],[112,38]],
      i:[[170,55],[170,80],[170,105],[155,68],[185,68],[155,95],[185,95],[170,40],[170,120],[160,82]],
      b:[[238,60],[225,92],[215,48],[260,82],[222,110],[268,52],[240,118],[212,70],[252,105],[228,38]]
    };

    function vennDots(o,a,i,b) {
        const counts={o:o,a:a,i:i,b:b}; let inner='';
        Object.keys(counts).forEach(k=>{
          const arr=POS[k]; const c=counts[k];
          for(let j=0;j<c;j++) { const p=arr[j%arr.length]; const ring=Math.floor(j/arr.length); inner += `<circle cx="${p[0]-ring*4}" cy="${p[1]+ring*4}" r="3.3" fill="#111"/>`; }
        });
        return vennFrame(inner);
    }

    function vennRegions(o,a,i,b) {
        return vennFrame(`<g font-family="serif" font-size="17" fill="#111" text-anchor="middle">
          <text x="302" y="33">${nfmt(o)}</text><text x="105" y="82">${nfmt(a)}</text><text x="170" y="82">${nfmt(i)}</text><text x="235" y="82">${nfmt(b)}</text>
        </g>`);
    }

    function vennPointProb(o,a,i,b) {
        const vals={o:o,a:a,i:i,b:b}; let inner='';
        Object.keys(vals).forEach(k=>{
          const arr=POS[k]; (vals[k]||[]).forEach((v,j)=>{ const p=arr[j%arr.length]; inner += `<circle cx="${p[0]}" cy="${p[1]}" r="2.7" fill="#111"/><text x="${p[0]+7}" y="${p[1]-5}" font-family="serif" font-size="12">${nfmt(v)}</text>`; });
        });
        return vennFrame(inner);
    }

